-- name: queries_listauditevents_select_audit_events_organization_id_ref_action :many
SELECT e.ref,COALESCE(p.ref,''),s.ref,s.display_name,COALESCE(a.ref,''),e.action,e.resource_kind,e.resource_ref,e.outcome,e.safe_summary,e.correlation_ref,e.occurred_at FROM control_plane.audit_events e LEFT JOIN control_plane.projects p ON p.id=e.project_id JOIN control_plane.subjects s ON s.id=e.actor_id LEFT JOIN control_plane.agents a ON a.id=e.assistant_agent_id WHERE e.organization_id=$1::uuid AND ($2='' OR p.ref=$2) AND ($3='' OR e.action=$3) AND ($4='' OR e.outcome=$4) AND ($5 IN ('OWNER','ADMINISTRATOR','AUDITOR') OR EXISTS(SELECT 1 FROM control_plane.memberships m WHERE m.project_id=e.project_id AND m.subject_id=$6::uuid AND m.active AND 'VIEW_AUDIT'=ANY(m.permissions))) ORDER BY e.occurred_at DESC LIMIT $7
